contract InvMutTest {
    C c;
    address creatorCandidate;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public function that tries to call migrateTo and asserts a general property
    function run(address callerAddr, address to) public payable {
        require(to != address(0), "to must be non-zero");
        // We will observe behavior of migrateTo when invoked by this contract (which is c's creator)
        // Read pre-state: contract balance and our recorded balance (via public getter not present for balances mapping)
        // balances mapping is not public in C, so we cannot read per-address balances; instead we observe address(c).balance

        uint256 beforeContractBal = address(c).balance;

        // Attempt migrateTo and record whether it reverted
        bool reverted;
        c.migrateTo(to); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint256 afterContractBal = address(c).balance;

        // General rule asserted:
        // If migrateTo succeeded (not reverted), then afterContractBal == 0 (contract's Ether forwarded out)
        // and the contract's balance decreased by at most the before amount (no creation of Ether): after <= before.
        // Also, if it succeeded, it must have forwarded exactly all Ether (so after == 0) and not increased balance.
        assert(
            (reverted && afterContractBal <= beforeContractBal) ||
            (!reverted && afterContractBal == 0 && beforeContractBal >= afterContractBal)
        );
    }

    // accept Ether so this contract can hold/send during tests
    receive() external payable {}
}

